mapper.select:
SELECT O.ORDER_ID, O.ORDER_TYPE, O.ORDER_STATUS, O.TOTAL_PRICE, O.DISCOUNT_AMT, O.USE_POINT, O.CREATED_AT, O.USER_ID, OI.ITEM_ID, P.PRODUCT_ID, P.PRODUCT_NAME, B.BRAND_NAME, C.CATEGORY_NAME, U.USER_NAME AS RECEIVER_NAME, U.USER_PHONE AS RECEIVER_PHONE, A.ZIPCODE, A.ADDRESS AS DELIVERY_ADDR, A.DETAILED_ADDRESS AS DELIVERY_DETAIL_ADDR, POI.ITEM_NAME AS OPTION_NAME,
/* 결제 */ COALESCE(PM.PAY_METHOD, 'CARD') AS PAY_METHOD, COALESCE(PM.PAID_AT, O.CREATED_AT) AS PAY_DATE, PM.EASY_PAY_PROVIDER,
/* 상품 */ P.PRODUCT_ID, P.PRODUCT_NAME, B.BRAND_NAME AS BRAND_NAME, C.CATEGORY_NAME AS CATEGORY_NAME,
OI.UNIT_PRICE AS ITEM_PRICE, P.DEPOSIT AS DEPOSIT, OI.QUANTITY AS ITEM_COUNT, O.ORDER_TYPE AS ITEM_TYPE, OI.START_DATE, OI.END_DATE,
/* 대표 이미지 */ (SELECT PI.IMG_URL FROM PRODUCT_IMG PI WHERE PI.PRODUCT_ID = P.PRODUCT_ID AND PI.IS_MAIN = 'Y' LIMIT 1) AS IMG_URL
FROM ORDERS O
INNER JOIN ORDER_ITEM OI ON O.ORDER_ID = OI.ORDER_ID
INNER JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID
/* 🔥 추가된 부분 */ LEFT JOIN BRAND B ON P.BRAND_ID = B.BRAND_ID
LEFT JOIN PRODUCT_CATEGORY C ON P.CATEGORY_ID = C.CATEGORY_ID
INNER JOIN USER U ON O.USER_ID = U.USER_ID
LEFT JOIN USER_ADDRESS A ON O.USER_ID = A.USER_ID AND A.DEFAULT_YN = 'Y'
LEFT JOIN PAYMENT PM ON O.ORDER_ID = PM.ORDER_ID
LEFT JOIN PAYMENT_HISTORY PH ON PM.PAY_ID = PH.TARGET_PAY_ID AND PH.NEW_STATUS = 'PAID'
LEFT JOIN PRODUCT_OPTION_ITEM POI ON OI.OPTION_ITEM_ID = POI.OPTION_ITEM_ID
WHERE O.ORDER_ID = #{orderId}
AND O.USER_ID = #{userId}

mapper.update:
UPDATE ORDERS
SET ORDER_STATUS = #{status}
WHERE ORDER_ID = #{orderId}
  AND ORDER_STATUS IN ('PAID', 'READY', 'PAY_COMPLETED')

UPDATE product_stock
SET RESERVED_QTY  = RESERVED_QTY  - #{quantity},
    AVAILABLE_QTY = AVAILABLE_QTY + #{quantity}
WHERE PRODUCT_ID    = #{productId}
  AND OPTION_ITEM_ID = #{optionItemId}
  AND STOCK_DATE BETWEEN #{startDate} AND DATE_SUB(#{endDate}, INTERVAL 1 DAY)
  AND RESERVED_QTY >= #{quantity}

UPDATE product_stock
SET AVAILABLE_QTY = LEAST(TOTAL_QTY, AVAILABLE_QTY + #{quantity})
WHERE PRODUCT_ID     = #{productId}
  AND OPTION_ITEM_ID = #{optionItemId}
  AND STOCK_DATE IS NULL

UPDATE USER
SET POINT = POINT + #{usePoint} - #{earnedPoint}
WHERE USER_ID = #{userId}

mapper.insert:
INSERT INTO product_stock (
    STOCK_DATE, PRODUCT_ID, OPTION_ITEM_ID,
    TOTAL_QTY, RESERVED_QTY, AVAILABLE_QTY
)
SELECT NULL, #{productId}, #{optionItemId}, 0, 0, 0
FROM dual
WHERE NOT EXISTS (
    SELECT 1 FROM product_stock
    WHERE PRODUCT_ID = #{productId}
    AND OPTION_ITEM_ID = #{optionItemId}
    AND STOCK_DATE IS NULL
)
